package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTlDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("Kanlungan Mula sa Masamang Kapwa", "O Allah, ako ay nagpapakupkop sa Iyo mula sa masamang kapitbahay sa lugar ng permanenteng paninirahan, dahil ang kapitbahay na nasa paglalakbay ay nagpapatuloy.", "Para sa proteksyon mula sa masamang kapitbahay.", "Ang Propeta ﷺ ay nag-utos na humingi ng kanlungan mula dito."),
        "dua_ishfi_abdak" to DuaText("Para sa Paggaling ng Maysakit", "O Allah, pagalingin Mo ang Iyong lingkod upang makaharap niya ang isang kaaway para sa Iyo o makalakad sa panalangin para sa Iyo.", "Para sa maysakit kapag bumibisita sa kanya.", "Itinuro ng Propeta ﷺ ang pagsasabi nito para sa mga may sakit."),
        "dua_la_mania" to DuaText("Walang Makakapigil sa Ibinibigay Mo", "Walang sinumang karapat-dapat sambahin maliban kay Allah, nag-iisa, walang katambal. Sa kanya ang kapangyarihan at sa Kanya ang papuri, at Siya ang may kapangyarihan sa lahat ng bagay. O Allah, walang makakapigil sa kung ano ang Iyong ibinibigay at walang makapagbibigay sa Iyong ipinagkait, at ang kayamanan ng mga mayayaman ay walang kabuluhan laban sa Iyo.", "Pagkatapos ng salam ng obligadong pagdarasal.", "Sinabi ito ng Propeta ﷺ pagkatapos ng bawat obligadong panalangin."),
        "dua_slaughtering" to DuaText("Kapag Katay ng Hayop", "Sa ngalan ng Allah, at si Allah ang Pinakamadakila.", "Kapag nag-aalay o nagkatay ng hayop.", "Ang Propeta ﷺ ay nagsabi ng Bismillah at takbir sa oras ng sakripisyo."),
        "dua_undressing" to DuaText("Kapag Naghuhubad ng Damit", "Sa ngalan ni Allah.", "Kapag naghuhubad ng damit (para sa ghusl o pagpapalit).", "Ito ay nagiging takip sa pagitan ng mga mata ng jinn at pribadong bahagi ng isang tao."),
        "dua_ilbas_jadidan" to DuaText("Nakikita ang Isang Tao sa Bagong Damit", "Magsuot ng bago, mamuhay na kapuri-puri at mamatay na martir.", "Nang makita ang isang kapatid na Muslim sa bagong damit.", "Ginawa ng Propeta ﷺ ang dua na ito sa pagkakita kay Umar (RA) sa bagong damit."),
        "dua_hajj_la_riya" to DuaText("Isang Hajj na Walang Pagpapakitang-tao", "O Allah, (gawin itong) isang Hajj na walang pakitang-tao at walang paghangad ng katanyagan.", "Para sa katapatan kapag gumagawa ng intensyon para sa Hajj.", "Ginawa ng Propeta ﷺ ang dua na ito sa panahon ng Hajj."),
        "dua_q_muslimayni_laka" to DuaText("Dua of Ibrahim & Ismail (AS) — Gawin Kaming Masunurin", "Panginoon namin, gawin Mo kaming pareho na masunurin sa Iyo at mula sa aming mga inapo ay isang bansang masunurin sa Iyo. Ipakita sa amin ang aming mga ritwal ng pagsamba at tanggapin ang aming pagsisisi. Katotohanan, Ikaw ang Tagatanggap ng pagsisisi, ang Maawain.", "Isang dua ng pagpapasakop para sa sarili at sa mga inapo.", "Ang dua ay ginawa habang itinatayo ang Ka'bah."),
        "dua_q_iftah_baynana" to DuaText("Dua ng Shu'aib (AS) — Hukom sa Pagitan Natin", "Aming Panginoon, humatol ka sa pagitan namin at ng aming mga tao sa katotohanan, at Ikaw ang pinakamahusay sa mga hukom.", "Para sa paghatol sa pagitan ng katotohanan at kasinungalingan.", "Ang dua ni Shu'ayb (AS) nang tanggihan siya ng kanyang mga tao."),
        "dua_q_la_akuna_zahiran" to DuaText("Dua ng Musa (AS) — Kailanman ay Katulong ng mga Kriminal", "Panginoon ko, dahil sa biyayang ipinagkaloob Mo sa akin, hinding-hindi ako magiging katulong ng mga kriminal.", "Pasasalamat sa mga pagpapala ni Allah at isang pangako na hindi tutulungan ang mga gumagawa ng masama.", "Ang pangako ni Musa (AS) pagkatapos ng kanyang pagsisisi."),
        "dua_q_nuh_unsurni" to DuaText("Dua of Nuh (AS) — Tulungan Mo Ako, Itinatanggi Nila Ako", "Panginoon ko, tulungan mo ako, sapagkat itinanggi nila ako.", "Kapag tinanggihan ka ng mga tao at tinanggihan ang katotohanan.", "Ang dua ng Nuh (AS), na sinagot."),
        "dua_q_ihkum_bil_haqq" to DuaText("Panginoon ko, Hukom ng Katotohanan", "Panginoon ko, humatol ka nang may katotohanan. At ang ating Panginoon ay ang Pinakamaawain, na ang tulong ay hinihingi laban sa kung ano ang iyong inilarawan.", "Sa harap ng mga kasinungalingan at maling paratang.", "Isang dua ang itinuro sa Propeta ﷺ."),
        "dua_ghalabatid_dayn" to DuaText("Kanlungan Mula sa Pagdurog ng Utang at Mga Kaaway", "O Allah, ako ay nagpapakupkop sa Iyo mula sa pagkalubog ng utang, mula sa pananakop ng isang kaaway at mula sa pagmamapuri ng mga kaaway.", "Proteksyon mula sa pasanin ng utang at dominasyon ng mga kaaway.", "Ang Propeta ﷺ ay dating naghahanap ng kanlungan mula sa mga bagay na ito."),
        "dua_faqr_qillah_dhillah" to DuaText("Kanlungan Mula sa Kahirapan at kahihiyan", "O Allah, ako ay nagpapakupkop sa Iyo mula sa kahirapan, kakapusan at kahihiyan, at mula sa paggawa ng masama sa iba o pagiging mali.", "Upang maging ligtas sa kahirapan, kagustuhan at kahihiyan.", "Isang kanlungan na itinuro ng Propeta ﷺ."),
        "dua_five_things_new_muslim" to DuaText("Magpatawad, Maawa, Patnubayan, Magpagaling, Magbigay", "O Allah, patawarin mo ako, maawa ka sa akin, patnubayan mo ako, bigyan mo ako ng kagalingan at paglaanan mo ako.", "Itinuro ng Propeta ﷺ ang dua na ito, kasama ang panalangin, sa mga bagong Muslim.", "Ang Propeta ﷺ ay nagsabi: ang mga salitang ito ay nagtitipon para sa iyo sa mundong ito at sa Kabilang Buhay."),
        "dua_ruku_laka_raka_tu" to DuaText("Sa Ruku — Sa Iyo Ako Yumuko", "O Allah, sa Iyo ako yumukod, sa Iyo ako ay naniwala at sa Iyo ako sumuko. Ang aking pandinig, ang aking paningin, ang aking isip, ang aking mga buto at ang aking mga litid ay nagpapakumbaba sa Iyo.", "Sa ruku (lalo na sa mga boluntaryong panalangin).", "Ang Propeta ﷺ ay binigkas ito sa ruku."),
        "dua_sujood_laka_sajadtu" to DuaText("Sa Sujood — Sa Iyo Ako Nagpatirapa", "O Allah, sa Iyo ako nagpatirapa, sa Iyo ako naniwala at sa Iyo ako sumuko. Ang aking mukha ay nagpatirapa sa Isa na lumikha nito, hinubog ito at inilabas ang pandinig at paningin nito. Pinagpala si Allah, ang pinakamahusay sa mga lumikha.", "Sa sujood (lalo na sa mga boluntaryong panalangin).", "Ang Propeta ﷺ ay binigkas ito sa sujood."),
        "dua_ruku_sujood_subhanaka" to DuaText("Luwalhati sa Iyo, Aming Panginoon - Patawarin Mo Ako", "Luwalhati sa Iyo, O Allah, aming Panginoon, at papuri sa Iyo. O Allah, patawarin mo ako.", "Sa ruku at sujood.", "Aisha (RA): madalas itong sinabi ng Propeta ﷺ sa ruku at sujood."),
        "dua_q_musa_li_akhi" to DuaText("Dua ni Musa (AS) — Patawarin Mo Ako at ang Aking Kapatid", "Panginoon ko, patawarin mo ako at ang aking kapatid at ipasok mo kami sa Iyong awa, sapagkat Ikaw ang Pinakamaawain sa mga mahabagin.", "Pagpapatawad para sa sarili at sa kapatid o mahal sa buhay.", "Ang dua ni Musa (AS) para kay Harun (AS)."),
        "dua_q_ufawwidu_amri" to DuaText("Ipinagkatiwala Ko ang Aking Pakikipag-ugnayan kay Allah", "At ipinagkakatiwala ko ang aking kapakanan kay Allah. Katotohanan, ang Allah ay Ganap na Nakikita ng Kanyang mga alipin.", "Kapag ang mga tao ay sumalungat sa iyo at ang usapin ay dapat na ipaubaya sa Allah.", "Ang mga salita ng mananampalataya mula sa bayan ni Faraon; Pagkatapos ay ipinagtanggol siya ni Allah mula sa kanilang masasamang balak."),
        "dua_q_hawariyyun" to DuaText("Dua ng mga Disipolo — Itala Kami Kasama ng mga Saksi", "Aming Panginoon, kami ay naniwala sa Iyong ipinahayag at kami ay sumunod sa Sugo, kaya itala kami sa mga saksi.", "Para sa katatagan sa pananampalataya at sa pagsunod sa Sugo.", "Ang dua ng mga alagad ng Isa (AS)."),
        "dua_q_la_tukhzini" to DuaText("Dua ni Ibrahim (AS) — Huwag Mo Akong Ipahiya", "At huwag mo akong kahihiyan sa Araw na sila ay muling nabuhay.", "Upang maging ligtas sa kahihiyan sa Araw ng Muling Pagkabuhay.", "Ang dua ni Ibrahim (AS) para sa Kabilang Buhay."),
        "dua_iftar_laka_sumtu" to DuaText("Iftar — Para Sa'yo Ako Nag-ayuno", "O Allah, para sa Iyo ako ay nag-ayuno at sa Iyong panustos ay sinisira ko ang aking pag-aayuno.", "Kapag nag-aayuno (ang kilalang iftar dua).", "Sinabi ito ng Propeta ﷺ sa iftar. Ito ay isang mursal na pagsasalaysay na pinalakas ng iba pang mga pagsasalaysay; ang pagbigkas nito sa iftar ay kaugalian ng mga Hanafi at ng karamihan."),
        "dua_iftar_ibn_umar" to DuaText("Iftar — Sa Iyong Malaking Awa, Patawarin Mo Ako", "O Allah, hinihiling ko sa Iyo sa pamamagitan ng Iyong awa na sumasaklaw sa lahat ng bagay na patawarin ako.", "Sa iftar - ginawa ni Abdullah ibn Amr (RA) itong dua; ang dua ng isang nag-aayuno sa iftar ay hindi tinatanggihan.", "Hadith: ang dua ng nag-aayuno sa oras ng iftar ay hindi tinatanggihan."),
        "dua_inni_saim" to DuaText("Kapag Nagalit Habang Nag-aayuno", "Ako ay nag-aayuno, ako ay nag-aayuno.", "Kapag may nang-iinsulto sa iyo o nakipag-away sa iyo habang nag-aayuno.", "Ang Propeta ﷺ ay nagsabi: ang pag-aayuno ay isang kalasag, kaya ang nag-aayuno ay hindi dapat magsalita ng kahalayan o kumilos nang walang kaalam-alam - kung may nag-aaway, sabihin ito ng dalawang beses."),
        "dua_eid_takbeer" to DuaText("Takbeer habang patungo sa Eid", "Si Allah ang Pinakamadakila, si Allah ang Pinakamadakila, walang diyos maliban sa Allah, at si Allah ang Pinakamadakila, si Allah ang Pinakamadakila, at ang lahat ng papuri ay para kay Allah.", "Mula sa gabi ng moonsighting hanggang sa Eid al-Fitr prayer, lalo na sa daan patungo sa Eid ground.", "Ang utos ng Quran: 'upang makumpleto mo ang pagbilang at ipahayag ang kadakilaan ng Allah' (al-Baqarah 2:185). Sinabi ni Ibn Mas'ud (RA) ang takbir na ito."),
        "dua_ahsin_aqibatana" to DuaText("Gawing Mabuti ang Ating Wakas sa Lahat ng Gawain", "O Allah, gawin mong mabuti ang aming wakas sa lahat ng mga gawain, at ipagtanggol mo kami sa kahihiyan sa mundong ito at parusa sa Kabilang Buhay.", "Para sa magandang kinalabasan sa bawat usapin.", "Ang sinumang gumawa ng dalawang ito at mamatay bago subukan ay mamamatay (ligtas mula sa pagsubok)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Hinihiling Ko ang Iyong Kaloob at Awa", "O Allah, hinihiling ko sa Iyo ang Iyong kagandahang-loob at ang Iyong awa, sapagkat walang sinuman ang nagtataglay nito maliban sa Iyo.", "Kapag humihingi ng probisyon at awa.", "Dumating ang mga panauhin sa Propeta ﷺ nang walang pagkain; ginawa niya itong dua, at may dumating na regalo."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Mga Salitang Itinuro sa isang Bedouin", "Walang sinumang karapat-dapat sambahin maliban kay Allah, nag-iisa, walang katambal. Si Allah ang Pinakamadakila, lubos; ang masaganang papuri ay para kay Allah; luwalhati kay Allah, Panginoon ng mga daigdig; at walang kapangyarihan o kapangyarihan maliban kay Allah, ang Makapangyarihan, ang Marunong.", "Isang komprehensibong parirala ng dhikr at dua — itinuro sa isang Bedouin.", "Pagkatapos nito ay tinuruan siyang magsabi ng 'Allahummaghfir li warhamni wahdini warzuqni'."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Patawarin ang Aking Ipinadala Bago at Pagkatapos", "O Allah, patawarin mo ako sa mga kasalanang nagawa ko noon at pagkatapos, kung ano ang aking ginawa sa lihim at kung ano ang aking ginawa nang hayagan, ang aking mga pagmamalabis, at kung ano ang Iyong higit na nalalaman kaysa sa akin. Ikaw ang Isa na nagdadala ng pasulong at ang Isa na nagbabalik; walang diyos maliban sa Iyo.", "Pagkatapos ng tashahhud at salawat, bago ang salam.", "Binibigkas ito ng Propeta ﷺ sa pagtatapos ng panalangin, sa pagitan ng tashahhud at salam."),
        "dua_jiddi_wa_hazli" to DuaText("Patawarin ang Aking Kaseryosohan at Aking Pagbibiro", "O Allah, patawarin mo ako sa mga kasalanang nagawa kong seryoso at sa pagbibiro, sa pagkakamali at sinasadya — at lahat ng iyon ay nasa akin.", "Kapatawaran para sa bawat uri ng kasalanan, kilala at hindi alam.", "Isang komprehensibong istighfar ng Propeta ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Pagkatapos ng Ruku — Pinuno ng Papuri ang Langit", "Panginoon namin, sa Iyo ang lahat ng papuri, pinupuno ang langit, pinupuno ang lupa, at pinupuno ang anumang naisin Mo pagkatapos noon.", "Pagkatapos bumangon mula sa ruku, kasama ang 'Rabbana lakal-hamd'.", "Ang Propeta ﷺ ay nagsabi nito sa pagbangon mula sa ruku."),
        "dua_istiftah_kabira" to DuaText("Si Allah ay Pinakamadakila, Saganang Pinupuri", "Si Allah ang Pinakamadakila, lubos; ang masaganang papuri ay para kay Allah; at luwalhati kay Allah sa umaga at gabi.", "Sa pagsisimula ng panalangin (isang anyo ng pambungad na papuri).", "Ang Propeta ﷺ ay nagsabi: ang mga pintuan ng langit ay nabuksan para dito."),
        "dua_q_ashku_bathhi" to DuaText("Dua ni Yaqub (AS) — Kay Allah Lamang Ako Nagrereklamo", "Sa Allah lamang ako nagrereklamo ng aking dalamhati at dalamhati.", "Sa malalim na kalungkutan at paghihiwalay.", "Sinabi ito ni Ya'qub (AS) sa kanyang paghihiwalay kay Yusuf (AS)."),
        "dua_q_khayrun_hafiza" to DuaText("Si Allah ang Pinakamahusay na Tagapagtanggol", "Si Allah ang pinakamahusay na Tagapagtanggol, at Siya ang Pinakamaawain sa mga mahabagin.", "Kapag nagpapadala ng mga bata o mga mahal sa buhay sa isang paglalakbay.", "Sinabi ito ni Ya'qub (AS) habang ipinagkatiwala ang kanyang anak kay Allah."),
        "dua_q_aqraba_rashada" to DuaText("Nawa'y Gabayan Ako ng Aking Panginoon na Mas Malapit sa Kanan", "Marahil ay gabayan ako ng aking Panginoon sa kung ano ang mas malapit kaysa dito sa tamang pag-uugali.", "Kapag naghahanap ng isang mas mahusay na paraan sa ilang bagay.", "Ang Propeta ﷺ ay sinabihan na sabihin ito sa pagkalimot."),
        "dua_q_sawa_as_sabil" to DuaText("Dua ni Musa (AS) — Gabayan Ako sa Tamang Daan", "Marahil ay patnubayan ako ng aking Panginoon sa tamang daan.", "Kapag nagtatakda sa isang bagong paglalakbay o isang hindi pamilyar na kalsada.", "Sinabi ito ni Musa (AS) habang lumingon siya patungo sa Madyan."),
        "dua_q_not_among_wrongdoers" to DuaText("Huwag Mo Akong Ilagay sa mga Makasalanan", "Panginoon ko, huwag mo akong ilagay sa mga taong gumagawa ng masama.", "Isang du'a na humihiling sa Allah na ilayo ang isa sa mga gumagawa ng masama.", "Isang du'a na humihiling sa Allah na ilayo ang isa sa mga gumagawa ng masama."),
        "dua_q_do_not_make_us_trial" to DuaText("Huwag Mo kaming Gawin na Pagsubok", "Aming Panginoon, huwag mo kaming gawing pagsubok sa mga hindi naniniwala, at patawarin mo kami, aming Panginoon. Tunay na Ikaw ang Makapangyarihan, ang Marunong.", "Ang dua ni Ibrahim (AS) at ng kanyang mga kasama.", "Ang dua ni Ibrahim (AS) at ng kanyang mga kasama."),
        "dua_morning_witness" to DuaText("Saksi sa Umaga sa Tawhid", "O Allah, ako ay pumasok sa umaga na nananawagan sa Iyo, sa mga may hawak ng Iyong Trono, sa Iyong mga anghel at sa lahat ng Iyong nilikha upang sumaksi na Ikaw ay si Allah, walang diyos maliban sa Iyo, nag-iisa, walang katambal, at si Muhammad ﷺ ay Iyong alipin at Sugo.", "Binanggit sa pagsasalaysay ang pagsasabi nito ng apat na beses sa umaga.", "Binanggit sa pagsasalaysay ang pagsasabi nito ng apat na beses sa umaga."),
    )
}
